/* ============================================
   VulnBank — Design System v2
   Blue brand palette, light/dark mode
   ============================================ */
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;1,400&family=Outfit:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* ================================================
   TOKENS — LIGHT MODE (default)
   ================================================ */
:root {
  /* Brand — derived from original #007BFF */
  --brand: #007BFF;
  --brand-light: #3D9BFF;
  --brand-dark: #0062CC;
  --accent: #007BFF;
  --accent-dim: #0062CC;
  --accent-text: #FFFFFF;

  /* Blue Scale (replaces navy, rooted in the original blue) */
  --navy-50:  #EFF6FF;
  --navy-100: #DBEAFE;
  --navy-200: #BFDBFE;
  --navy-300: #7CB3F5;
  --navy-400: #4A90E2;
  --navy-500: #2B6CB0;
  --navy-600: #1A5091;
  --navy-700: #123B6E;
  --navy-800: #0C2A50;
  --navy-900: #071B37;
  --navy-950: #041020;

  /* Surface (light) */
  --bg:       #F6F8FB;
  --surface:  #FFFFFF;
  --surface-2: #F0F2F5;
  --surface-3: #E8EBF0;
  --border:   #E2E6ED;
  --border-2: #D0D5DD;

  /* Text (light) */
  --text-1:   #0D1B33;
  --text-2:   #3D4F65;
  --text-3:   #6B7A8D;
  --text-4:   #9BA7B5;

  /* Semantic */
  --green:     #10B981;
  --green-bg:  #ECFDF5;
  --green-text:#065F46;
  --red:       #EF4444;
  --red-bg:    #FEF2F2;
  --red-text:  #991B1B;
  --amber:     #F59E0B;
  --amber-bg:  #FFFBEB;
  --amber-text:#92400E;
  --sky:       #0EA5E9;
  --sky-bg:    #F0F9FF;
  --sky-text:  #075985;

  /* Sidebar (always dark, both modes) */
  --sidebar-bg:      #0C2A50;
  --sidebar-surface:  rgba(255,255,255,0.06);
  --sidebar-border:   rgba(255,255,255,0.06);
  --sidebar-text-1:   rgba(255,255,255,0.9);
  --sidebar-text-2:   rgba(255,255,255,0.5);
  --sidebar-text-3:   rgba(255,255,255,0.3);
  --sidebar-hover:    rgba(255,255,255,0.08);
  --sidebar-active:   rgba(255,255,255,0.12);

  /* Typography */
  --font-display: 'Plus Jakarta Sans', system-ui, sans-serif;
  --font-body:    'Outfit', system-ui, sans-serif;
  --font-mono:    'JetBrains Mono', ui-monospace, monospace;

  /* Radii */
  --r-sm:   6px;
  --r-md:   10px;
  --r-lg:   14px;
  --r-xl:   20px;
  --r-2xl:  28px;
  --r-full: 9999px;

  /* Shadows (light) */
  --shadow-sm:  0 1px 2px rgba(0,0,0,0.04), 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md:  0 4px 12px rgba(0,0,0,0.05), 0 1px 4px rgba(0,0,0,0.04);
  --shadow-lg:  0 10px 32px rgba(0,0,0,0.07), 0 2px 8px rgba(0,0,0,0.04);
  --shadow-xl:  0 20px 60px rgba(0,0,0,0.10), 0 4px 16px rgba(0,0,0,0.04);
  --shadow-glow: 0 0 20px rgba(0,123,255,0.15);

  /* Motion */
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --dur-fast: 150ms;
  --dur-mid:  250ms;
  --dur-slow: 500ms;

  /* Layout */
  --sidebar-w: 260px;
  --topbar-h:  64px;
